import base64, sys, io
F="MyPersonas.Online_v0/index.html"
OLD_B64=""
NEW_B64=""
old=base64.b64decode(OLD_B64).decode("utf-8")
new=base64.b64decode(NEW_B64).decode("utf-8")
raw=open(F,"rb").read().decode("utf-8")
lf=raw.replace("\r\n","\n")
if new in lf:
    print("ALREADY_PATCHED"); sys.exit(0)
n=lf.count(old)
if n!=1:
    print("MATCH_COUNT=%d (expected 1) - aborting"%n); sys.exit(2)
lf2=lf.replace(old,new)
open(F,"wb").write(lf2.replace("\n","\r\n").encode("utf-8"))
print("PATCHED ok; new_len=%d"%len(lf2))
